    titleHi: "उड़ान (UDAN — उड़े देश का आम नागरिक) योजना",
    summaryEn: "Regional Connectivity Scheme (RCS) making air travel affordable for common citizens and connecting unserved/underserved airports, heliports, and water aerodromes.",
    summaryHi: "आम नागरिकों के लिए हवाई यात्रा को किफायती बनाने और देश के अनछुए व कम सेवा वाले हवाई अड्डों, हेलीपोर्ट व वाटर एयरोड्रोम को जोड़ने वाली क्षेत्रीय संपर्क योजना।",
    keyProvisionsEn: [
      "Provides Viability Gap Funding (VGF) to airlines along with airport/utility concessions from States and AAI.",
      "Operationalized 687 regional routes connecting 95 aerodromes (including 17 heliports & 2 water aerodromes), carrying 1.72 crore passengers.",
      "Modified UDAN (launched 4 July 2026) targets 100 new airports from unserved airstrips, 200 modern helipads, and Challenge Mode aerodrome development.",
    ],
    keyProvisionsHi: [
      "एयरलाइंस को वायबिलिटी गैप फंडिंग (VGF) तथा राज्यों व AAI द्वारा हवाई अड्डा/यूटिलिटी रियायतें।",
      "687 क्षेत्रीय मार्गों पर 95 एयरोड्रोम (17 हेलीपोर्ट व 2 वाटर एयरोड्रोम सहित) चालू और 1.72 करोड़ यात्रियों को सेवा।",
      "मॉडिफाइड उड़ान (4 जुलाई 2026) के तहत 100 नए हवाई अड्डे, 200 आधुनिक हेलीपैड और चैलेंज मोड विकास।",
    ],
    prelimsFactsEn: [
      "Launched: October 2016 (1st flight Shimla–Delhi, April 2017); Modified UDAN: 4 July 2026.",
      "Implementing Agency: Airports Authority of India (AAI).",
      "India's operational airports grew from 74 (2014) to 166.",
    ],
    prelimsFactsHi: [
      "शुभारंभ: अक्टूबर 2016 (पहली उड़ान शिमला-दिल्ली, अप्रैल 2017); मॉडिफाइड उड़ान: 4 जुलाई 2026।",
      "कार्यान्वयन एजेंसी: भारतीय विमानपत्तन प्राधिकरण (AAI)।",
      "देश में संचालित हवाई अड्डों की संख्या 2014 के 74 से बढ़कर 166 हुई।",
    ],
    mainsAngleEn: "Democratizes aviation, integrates North-East and hilly/island regions, and stimulates regional tourism and commerce.",
    mainsAngleHi: "हवाई यात्रा का लोकतंत्रीकरण करती है, पूर्वोत्तर व पर्वतीय क्षेत्रों को जोड़ती है और क्षेत्रीय पर्यटन व व्यापार को बढ़ावा देती है।",
    sourceUrl: "https://www.pib.gov.in/FactsheetDetails.aspx?id=151125&NoteId=151125&ModuleId=16&reg=44&lang=1",
