    mainsAngleEn: "Curbs excessive urea/chemical fertilizer overuse, lowers input costs, and promotes climate-resilient soil conservation.",
    mainsAngleHi: "असंतुलित रासायनिक उर्वरक उपयोग पर अंकुश लगाती है, कृषि लागत घटाती है और टिकाऊ मृदा संरक्षण सुनिश्चित करती है।",
