    mainsAngleEn: "Directly cuts India's high Out-of-Pocket Expenditure (OOPE) on healthcare and promotes generic medicine confidence.",
    mainsAngleHi: "स्वास्थ्य सेवाओं पर होने वाले भारी 'आउट-ऑफ-पॉकेट खर्च' (OOPE) को कम कर गरीब व मध्यम वर्ग को बड़ी आर्थिक राहत देती है।",
    sourceUrl: "https://www.pib.gov.in/FeaturesDeatils.aspx?id=160014&NoteId=160014&ModuleId=2&reg=3&lang=1",
