      "कानूनी आधार: भारतीय वन (संशोधन) अधिनियम, 2017 द्वारा गैर-वन बांस को 'वृक्ष' की परिभाषा से बाहर किया गया।",
      "फोकस: गैर-वन बांस की खेती और आयात प्रतिस्थापन।",
