    mainsAngleEn: "Prevents brain drain from pure sciences into purely commercial degrees by incentivizing early scientific curiosity and research careers.",
    mainsAngleHi: "कम उम्र से ही वैज्ञानिक जिज्ञासा व बुनियादी विज्ञान अध्ययन को प्रोत्साहित कर भारत के R&D मानव संसाधन आधार को मजबूत बनाती है।",
    sourceUrl: "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2241758&reg=3&lang=1",
