    summaryHi: "15–29 वर्ष के युवाओं को अनुभवात्मक शिक्षा, स्वैच्छिक सेवा, नेतृत्व और करियर अवसरों से जोड़ने वाला स्वायत्त 'फिजिटल' (भौतिक + डिजिटल) राष्ट्रीय मंच।",
