      "प्रति वर्ष लगभग 47+ बिलियन kWh बिजली की बचत और ~9,500 MW पीक डिमांड में कमी।",
      "बिना किसी प्रत्यक्ष सरकारी सब्सिडी के प्रति वर्ष ~3.8 करोड़ टन CO2 उत्सर्जन में कमी।",
