    mainsAngleEn: "Case study in market-led climate action—using public demand aggregation rather than subsidies to drive clean-tech adoption.",
    mainsAngleHi: "बाजार-आधारित जलवायु कार्रवाई का उत्कृष्ट उदाहरण—जहां सब्सिडी के बजाय थोक सरकारी मांग से स्वच्छ तकनीक की कीमतें घटाई गईं।",
    sourceUrl: "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2090639&reg=3&lang=2",
